import { Costmdls, HexBlob, Redeemer, Redeemers, SLOT_CONFIG_NETWORK, fromHex, toHex } from "@blaze-cardano/core";
import * as U from "@blaze-cardano/uplc/wasm";

//#region src/vm.ts
/**
* This function returns an evaluator function that can be used to evaluate a transaction.
* The evaluator function uses the UPLC (Untyped Plutus Core) evaluator to simulate the execution of scripts.
* @param params - The protocol parameters.
* @param overEstimateSteps - The overestimation factor for execution steps.
* @param overEstimateMem - The overestimation factor for memory.
* @param slotConfig - The slot configuration to be used. Defaults to Mainnet.
* @returns An evaluator function.
*/
function makeUplcEvaluator(params, overEstimateSteps, overEstimateMem, slotConfig = SLOT_CONFIG_NETWORK.Mainnet) {
	return (draft_tx, allUtxos) => {
		const uplcResults = U.eval_phase_two_raw(fromHex(draft_tx.toCbor()), allUtxos.map((x) => fromHex(x.input().toCbor())), allUtxos.map((x) => fromHex(x.output().toCbor())), fromHex(Costmdls.fromCore(params.costModels).toCbor()), BigInt(Math.floor(params.maxExecutionUnitsPerTransaction.steps / (overEstimateSteps ?? 1))), BigInt(Math.floor(params.maxExecutionUnitsPerTransaction.memory / (overEstimateMem ?? 1))), BigInt(slotConfig.zeroTime), BigInt(slotConfig.zeroSlot), slotConfig.slotLength);
		const redeemerValues = [];
		for (const result of uplcResults) {
			const redeemerBytes = result.redeemer;
			const redeemer = Redeemer.fromCbor(HexBlob(toHex(redeemerBytes)));
			const exUnits = redeemer.exUnits();
			exUnits.setSteps(BigInt(Math.round(Number(exUnits.steps()) * overEstimateSteps)));
			exUnits.setMem(BigInt(Math.round(Number(exUnits.mem()) * overEstimateMem)));
			redeemer.setExUnits(exUnits);
			redeemerValues.push(redeemer);
		}
		const redeemers = Redeemers.fromCore([]);
		redeemers.setValues(redeemerValues);
		return Promise.resolve(redeemers);
	};
}

//#endregion
export { makeUplcEvaluator };